{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Tolfenamic acid, a diarylamine carboxylic acid with an acidic ionizable group, has an absolute oral bioavailability of 63.2% in healthy female volunteers, directly supporting F ≥ 20% for the query's acidic N-arylamine sulfonylurea.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Bumetanide, a polar aniline/sulfonamide/carboxylic acid with high TPSA and negative logD, shows oral bioavailability of 0.664 in healthy subjects, demonstrating that polar acidic structures can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Nicotinic acid, a small pyridine acid, has about 90% systemic availability in humans, supporting high F for the pyridine-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Isoniazid, a pyridine derivative, has 93% absolute bioavailability in fasting TB patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Y-20811, an acidic aromatic carboxylic acid, has oral bioavailability of 0.72-0.81, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Isradipine has low oral bioavailability (~16%) in healthy subjects, a contradictory example; however, it is a neutral dihydropyridine ester with extensive first-pass metabolism, unlike the acidic sulfonylurea query, so it is outweighed by the high-F acidic analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is predicted to have high absolute oral bioavailability (F ≥ 20%). Multiple high-transfer analogues with acidic/ionizable aromatic structures (tolfenamic acid, bumetanide, nicotinic acid, isoniazid, Y-20811) show F values mostly 60-95%, outweighing the single low-F isradipine example, which is structurally and mechanistically distinct. The physicochemical prior of poor permeability is overridden by direct experimental evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the exact query molecule.",
    "No analogue with a sulfonylurea group; closest are acidic arylamine/carboxylic acid drugs.",
    "First-pass metabolism and transporter effects for the sulfonylurea moiety are not directly characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

